import {GAME} from './config.js';
import * as E from './engine.js';
import {MAX_LEVEL,MODERN,CAMP_NAMES,ALLIES} from './catalog.js';
import {Battlefield,ready,thumbnail} from './scene.js';
import {icon} from './icons.js';
import {sound} from './sound.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.floor(n).toLocaleString('es-CO'),clock=n=>{n=Math.max(0,Math.ceil(n));return n<60?n+' s':Math.floor(n/60)+' m '+n%60+' s';};
const KEY=GAME.id+'-campaign-v1';let state,loadError='',broken='',storageOk=true;
try{const raw=localStorage.getItem(KEY);state=raw?E.decode(raw):E.createState();}catch(error){broken=localStorage.getItem(KEY)||'';loadError=error.message;state=E.createState();}
document.title=GAME.title+' · Estrategia y conquista';document.body.dataset.theme=GAME.theme;$('#brand-name').textContent=GAME.short;$('#help-button').innerHTML=icon('help');$('#settings-button').innerHTML=icon('settings');$('#sound-button').innerHTML=icon('sound');$$('[data-action=center]').forEach(el=>el.innerHTML=icon('target'));$$('[data-action=rotate]').forEach(el=>el.innerHTML=icon('rotate'));$$('[data-action=pan]').forEach(el=>el.innerHTML=icon('move'));$('[data-action=collect-all]').innerHTML=icon('coin')+' Recoger producción';sound.enabled=state.settings.sound;sound.volume=state.settings.volume;
let scene,tab='base',category='all',unitCategory='all',selected=[],tool=null,moving=null,candidate=null,deployType=null,command='attack',pendingImport=null,toastTimer,lastSave=0,dirty=true,unitFilter='',thumbnailJob=0;
const overlay=$('#overlay'),ctx=overlay.getContext('2d');
function save(){if(loadError)return;try{localStorage.setItem(KEY,E.encode(state));storageOk=true;lastSave=state.time;}catch{storageOk=false;}$('#save-status').textContent=storageOk?'Guardado local':'Sin guardar · exporta una copia';}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function act(result,cue='select'){if(result){toast(result.message);sound.play(result.ok?cue:'error');if(result.ok){save();dirty=true;}}return result;}
function cost(values){return'<div class="cost">'+Object.entries(values||{}).map(([key,value])=>'<span class="'+(state.resources[key]<value?'missing':'')+'" title="'+esc(GAME.resources[key]?.name)+'">'+icon(GAME.resources[key]?.icon)+' '+fmt(value)+'</span>').join('')+'</div>';}
function img(type,level=1,unit=false,cls=''){return'<img class="'+cls+'" data-thumb="'+type+'" data-level="'+level+'" data-unit="'+unit+'" alt="'+esc(unit?E.UNITS[type]?.name:E.BUILDINGS[type]?.name)+'" width="180" height="170">';}
function thumbs(root=document){cancelAnimationFrame(thumbnailJob);thumbnailJob=requestAnimationFrame(()=>{for(const image of root.querySelectorAll('img[data-thumb]')){try{image.src=thumbnail(image.dataset.thumb,Number(image.dataset.level),image.dataset.unit==='true');}catch{image.alt='Modelo 3D';}}});}
const head=(eyebrow,title)=>'<div class="panel-top"><div><div class="eyebrow">'+eyebrow+'</div><h2>'+title+'</h2></div><button class="close" data-action="close-modal" aria-label="Cerrar">'+icon('close')+'</button></div>';
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();thumbs($('#modal'));}
function setTab(next){tab=tab===next&&next!=='base'?'base':next;selected=[];tool=null;moving=null;candidate=null;scene?.setPlacement(null);dirty=true;render();}
function nav(){const q=E.QUESTS.filter(q=>!state.claimed.includes(q.id)&&q.value(state)>=q.target).length;$('#navigation').innerHTML=[['base','home','Mi base'],['build','build','Construir'],['army','army','Ejército'],['campaign','map','Campaña'],['tasks','tasks','Encargos']].map(([id,i,label])=>'<button data-action="tab" data-type="'+id+'" class="'+(tab===id?'active':'')+'" aria-current="'+(tab===id?'page':'false')+'">'+icon(i)+'<span>'+label+'</span>'+(id==='tasks'&&q?'<b class="badge">'+q+'</b>':'')+'</button>').join('');}
function renderHud(){const cap=E.storageCap(state);$('#resources').innerHTML=E.RESOURCE_KEYS.map(k=>'<div class="resource" title="'+esc(GAME.resources[k].name)+' · capacidad '+fmt(cap)+'">'+icon(GAME.resources[k].icon)+'<span><small>'+esc(GAME.resources[k].name)+'</small><b>'+fmt(state.resources[k])+'</b></span><div class="cap"><span style="width:'+Math.min(100,state.resources[k]/cap*100)+'%"></span></div></div>').join('');$('#builder-status').innerHTML=icon('build')+(E.builders(state)-E.usedBuilders(state))+' / '+E.builders(state)+' constructores libres';$('#army-status').innerHTML=icon('army')+E.population(state)+' / '+E.populationCap(state)+' de capacidad';const battle=state.battle;$('#world-kicker').textContent=battle?battle.kind==='raid'?'ALERTA · DEFIENDE TU BASE':'OPERACIÓN · '+E.DIFFICULTIES[state.difficulty].name.toUpperCase():MODERN?'OPERACIÓN VANGUARDIA · '+E.DIFFICULTIES[state.difficulty].name.toUpperCase():'CRÓNICAS DE UN REINO · '+E.DIFFICULTIES[state.difficulty].name.toUpperCase();$('#world-name').textContent=battle?battle.name:MODERN?'Fuerte Aurora':'Reino de Aurora';$('#world-detail').textContent=battle?'Las bajas son permanentes. Los supervivientes regresan a casa.':GAME.hq+' '+E.hqLevel(state)+' · Nivel '+(1+Math.floor(state.xp/300))+' · '+state.army.length+' tropas';document.body.classList.toggle('in-battle',!!battle);$('.bottom-left').hidden=tab!=='base'||selected.length>0||!!tool||!!battle;$('#battle-bar').hidden=!battle;if(battle){const destroyed=battle.buildings.filter(x=>x.hp<=0).length;$('#battle-bar').innerHTML=icon('clock')+'<div><strong>'+clock(battle.limit-battle.elapsed)+'</strong><br><small>'+destroyed+' / '+battle.initialBuildings+' edificios destruidos</small></div><button data-action="retreat" class="danger">'+(battle.kind==='raid'?'Finalizar defensa':'Retirar ejército')+'</button>';}}
function panelHead(kicker,title){return'<div class="panel-top"><div><div class="eyebrow">'+kicker+'</div><h2>'+title+'</h2></div><button class="close" data-action="close-panel" aria-label="Cerrar panel">'+icon('close')+'</button></div>';}
function buildPanel(){const categories={all:'Todo',production:'Recursos',military:'Ejército',defense:'Defensa',economy:'Economía',support:'Servicios',science:'Ciencia'};return panelHead('DISEÑA TU BASE','Cada edificio cuenta.')+'<p class="intro">'+E.usedBuilders(state)+' obras en marcha. Toca un plano y marca su lugar en el mapa.</p><div class="chips">'+Object.entries(categories).map(([key,label])=>'<button data-action="category" data-type="'+key+'" class="'+(category===key?'active':'')+'">'+label+'</button>').join('')+'</div><div class="cards">'+Object.values(E.BUILDINGS).filter(b=>b.type!=='hq'&&b.id!=='hq'&&(category==='all'||b.kind===category)).map(b=>{const locked=E.hqLevel(state)<b.hq,count=state.buildings.filter(v=>v.type===b.id).length;return'<article class="card '+(locked?'locked':'')+'">'+img(b.id)+'<span class="card-level">'+(locked?GAME.hq+' '+b.hq:count+' / '+b.limit)+'</span><h3>'+esc(b.name)+'</h3><p>'+esc(b.description)+'</p>'+cost(b.cost)+'<button data-action="place" data-type="'+b.id+'" '+(locked||count>=b.limit?'disabled':'')+'>'+icon(locked?'shield':'plus')+(locked?'Nivel '+b.hq:'Construir')+'</button></article>';}).join('')+'</div><button class="secondary wide" data-action="clear-terrain">'+icon('build')+' Despejar árbol o roca · 15 oro</button>';}
function armyPanel(){const categories={all:'Todo',infantry:'Infantería',range:MODERN?'Especialistas':'Arqueros y magia',vehicle:MODERN?'Vehículos':'Monturas y asedio',air:MODERN?'Aeronaves':'Criaturas'};const queues=state.training.length?'<div class="section-label">Entrenamiento en curso</div><div class="queue">'+state.training.map(j=>'<div class="queue-item">'+img(j.type,j.level,true)+'<div><b>'+esc(E.UNITS[j.type].name)+'</b><div class="progress"><span style="width:'+Math.max(0,(state.time-j.started)/(j.ends-j.started)*100)+'%"></span></div><small>'+clock(j.ends-state.time)+'</small></div><button data-action="cancel-training" data-id="'+j.id+'" aria-label="Cancelar entrenamiento">'+icon('close')+'</button></div>').join('')+'</div>':'';
 const study=state.study?'<div class="warning">'+icon('research')+' Investigando '+esc(E.UNITS[state.study.type].name)+' · grado '+state.study.level+' · '+clock(state.study.ends-state.time)+'</div>':'';
 return panelHead('ENTRENAR · INVESTIGAR · DESPLEGAR','Tu fuerza de combate.')+'<p>Capacidad '+E.population(state)+' / '+E.populationCap(state)+'. Los edificios militares entrenan en paralelo. Las bajas necesitan nuevos reemplazos.</p>'+queues+study+'<div class="chips">'+Object.entries(categories).map(([key,label])=>'<button data-action="unit-category" data-type="'+key+'" class="'+(unitCategory===key?'active':'')+'">'+label+'</button>').join('')+'</div><div class="cards">'+Object.values(E.UNITS).filter(u=>unitCategory==='all'||u.factory===unitCategory).map(u=>{const factory=E.availableFactory(state,u.id),locked=E.hqLevel(state)<u.hq||!factory,count=state.army.filter(a=>a.type===u.id).length,level=E.unitLevel(state,u.id),stats=E.unitStats(u.id,level);return'<article class="card '+(locked?'locked':'')+'">'+img(u.id,level,true)+'<span class="card-level">'+(locked?'Base '+u.hq:'Grado '+level)+'</span><h3>'+esc(u.name)+'</h3><small>'+fmt(stats.hp)+' vida · '+(u.heal?'cura '+u.heal:stats.damage+' daño')+' · '+u.pop+' plazas</small><p>'+(locked?esc(E.BUILDINGS[u.factory].name)+' '+u.required+' · '+GAME.hq+' '+u.hq:count+' en la base · '+clock(u.time))+'</p>'+cost(u.cost)+'<button data-action="train" data-type="'+u.id+'" '+(locked?'disabled':'')+'>'+icon('plus')+' Entrenar</button><button data-action="unit-detail" data-type="'+u.id+'">Ficha y mejoras '+icon('arrow')+'</button></article>';}).join('')+'</div>';}
function campaignPanel(){return panelHead('DOCE TERRITORIOS · TRES ESTRELLAS','La frontera te espera.')+'<p class="intro">Espía cada base antes de atacar. El botín se obtiene con la victoria; las conquistas repetidas entregan el 25%. Rivales de IA.</p><div class="campaign-list">'+CAMP_NAMES.map((name,i)=>{const locked=i>0&&!state.completed[i-1],stars=state.completed[i]||0;return'<article class="camp-card '+(locked?'locked':'')+'"><div class="camp-number">'+String(i+1).padStart(2,'0')+'</div><div><h3>'+esc(name)+'</h3><small>'+('Dificultad '+Math.min(10,Math.ceil((i+1)*.72)))+' · '+(locked?'Ruta cerrada':'Base de '+GAME.enemy)+'</small><span class="stars">'+'★'.repeat(stars)+'☆'.repeat(3-stars)+'</span></div><button data-action="scout" data-index="'+i+'" aria-label="Espiar '+esc(name)+'" '+(locked?'disabled':'')+'>'+icon(locked?'shield':'arrow')+'</button></article>';}).join('')+'</div><div class="section-label">Diplomacia con facciones de IA</div>'+ALLIES.map(a=>{const p=state.alliances[a.id]||{reputation:0,next:0},has=state.buildings.some(b=>b.type==='embassy'&&!b.job&&b.hp>0),amount=120+p.reputation*40;return'<div class="quest-card"><h3>'+esc(a.name)+'</h3><p>Reputación '+p.reputation+'. Entrega '+amount+' '+GAME.resources[a.need].name.toLowerCase()+' para recibir '+Math.round(amount*1.5)+' oro'+(a.need!=='supply'?' y 70 '+GAME.resources.supply.name.toLowerCase():'')+'.</p><button data-action="ally" data-id="'+a.id+'" '+(!has||state.time<p.next?'disabled':'')+'>'+(!has?'Necesita embajada':state.time<p.next?'Próximo encargo en '+clock(p.next-state.time):'Entregar suministros')+'</button></div>';}).join('');}
function tasksPanel(){return panelHead('UNA BASE CON PROPÓSITO','Pequeños grandes pasos.')+'<p class="intro">Las recompensas ayudan a crecer. Recógelas cuando hayas completado el encargo.</p>'+E.QUESTS.map(q=>{const value=Math.min(q.target,q.value(state)),claimed=state.claimed.includes(q.id),done=value>=q.target;return'<article class="quest-card"><h3>'+esc(q.name)+'</h3><p>'+esc(q.text)+'</p><div class="progress"><span style="width:'+value/q.target*100+'%"></span></div><small>'+value+' / '+q.target+'</small>'+cost(q.reward)+'<button class="'+(done&&!claimed?'primary':'')+'" data-action="claim" data-id="'+q.id+'" '+(!done||claimed?'disabled':'')+'>'+(claimed?'Recompensa recogida':done?'Recoger recompensa':'En progreso')+'</button></article>';}).join('')+'<div class="section-label">Diario de la base</div>'+state.log.slice(0,15).map(l=>'<p class="log-entry">'+esc(l.message)+'</p>').join('');}
function renderPanel(){const panel=$('#panel');panel.hidden=tab==='base'||!!state.battle;if(panel.hidden)return;panel.innerHTML=tab==='build'?buildPanel():tab==='army'?armyPanel():tab==='campaign'?campaignPanel():tasksPanel();thumbs(panel);}
function renderInspector(){const panel=$('#inspector'),building=state.buildings.find(b=>b.id===selected[0]);panel.hidden=!building||tab!=='base'||!!state.battle||!!tool;if(panel.hidden)return;const b=building,spec=E.BUILDINGS[b.type],stats=E.buildingStats(b.type,b.level),q=E.upgradeQuote(state,b.id),prod=spec.resource?'<div class="stat-row"><span>Producción</span><strong>'+stats.rate.toFixed(1)+' / s</strong></div><div class="stat-row"><span>Preparado para recoger</span><strong>'+fmt(b.stored)+' / '+fmt(stats.capacity)+'</strong></div><button class="primary wide" data-action="collect" data-id="'+b.id+'" '+(b.stored<1||!!b.job||b.hp<=0?'disabled':'')+'>'+icon('coin')+' Recoger '+fmt(b.stored)+'</button>':'',job=b.job?'<div class="section-label">'+(b.job.kind==='upgrade'?'Mejorando':b.job.kind==='repair'?'Reparando':'Construyendo')+'</div><div class="progress"><span style="width:'+(state.time-b.job.started)/(b.job.ends-b.job.started)*100+'%"></span></div><div class="timer">'+clock(b.job.ends-state.time)+' restantes</div>':'';
 panel.innerHTML='<div class="panel-top"><div><div class="eyebrow">GESTIONAR EDIFICIO</div><h2>'+esc(spec.name)+'</h2></div><button class="close" data-action="deselect" aria-label="Cerrar edificio">'+icon('close')+'</button></div>'+img(b.type,b.level,false,'hero-image')+'<span class="level-pill">NIVEL '+b.level+' / '+MAX_LEVEL+'</span><p>'+esc(spec.description)+'</p><div class="stat-row"><span>Integridad</span><strong>'+fmt(b.hp)+' / '+fmt(stats.hp)+'</strong></div>'+(stats.attack?'<div class="stat-row"><span>Daño / alcance</span><strong>'+stats.attack+' / '+stats.range.toFixed(1)+'</strong></div>':'')+prod+job+(b.hp<stats.hp&&!b.job?'<button class="wide" data-action="repair" data-id="'+b.id+'">'+icon('build')+' '+(b.hp<=0?'Reconstruir':'Reparar')+'</button>':'')+(!b.job&&b.hp>0?'<button class="primary wide" data-action="upgrade-preview" data-id="'+b.id+'" '+(b.level>=MAX_LEVEL?'disabled':'')+'>'+icon('plus')+(b.level>=MAX_LEVEL?'Nivel máximo':'Ver mejora al nivel '+(b.level+1))+'</button><button class="wide secondary" data-action="move-building" data-id="'+b.id+'">'+icon('move')+' Mover edificio</button>':'');thumbs(panel);}
function renderPlacement(){const p=$('#placement');p.hidden=!tool&&!moving;if(p.hidden)return;const spec=E.BUILDINGS[tool]||E.BUILDINGS[state.buildings.find(b=>b.id===moving)?.type],clear=tool==='clear';p.innerHTML='<div><strong>'+(clear?'Despejar terreno':moving?'Mover '+esc(spec?.name):esc(spec?.name))+'</strong><p>'+(candidate?'Posición '+candidate.x+', '+candidate.y:'Toca suelo libre para marcar el lugar.')+'</p>'+(!clear&&!moving?cost(spec?.cost):'')+'</div>'+(candidate&&!clear?'<button class="primary" data-action="confirm-placement">Confirmar</button>':'')+'<button data-action="cancel-placement" aria-label="Cancelar colocación">'+icon('close')+'</button>';}
function renderDock(){const dock=$('#army-dock'),b=state.battle;dock.hidden=!b;if(!b)return;const counts={};for(const u of b.reserve)counts[u.type]=(counts[u.type]||0)+1;dock.innerHTML=(Object.keys(counts).length?Object.entries(counts).map(([type,n])=>'<button class="troop-chip '+(deployType===type?'active':'')+'" data-action="deployment-type" data-type="'+type+'">'+img(type,E.unitLevel(state,type),true)+'<b>'+n+'</b><span>'+esc(E.UNITS[type].name)+'</span></button>').join('')+'<button class="deploy-all primary" data-action="deploy-all">Desplegar<br>ejército</button>':'')+'<button class="deploy-all" data-action="select-all">'+icon('army')+'<br>Seleccionar<br>todas</button><button class="deploy-all '+(command==='attack'?'primary':'')+'" data-action="attack-mode">'+icon('target')+'<br>Avanzar<br>y atacar</button><button class="deploy-all '+(command==='move'?'primary':'')+'" data-action="move-mode">'+icon('move')+'<br>Mover</button><button class="deploy-all" data-action="hold">'+icon('shield')+'<br>Detener</button>';thumbs(dock);}
function render(){renderHud();nav();renderPanel();renderInspector();renderPlacement();renderDock();dirty=false;}
function difficultyOptions(){return'<div class="difficulty-options">'+Object.entries(E.DIFFICULTIES).map(([id,d])=>'<button data-action="difficulty" data-type="'+id+'" aria-pressed="'+(state.difficulty===id)+'"><strong>'+d.name+'</strong><span>'+({easy:'Amenazas reducidas para construir y aprender.',hard:'Ejércitos peligrosos y recompensas mayores.',simulation:'Mayor daño rival, incursiones frecuentes y máximo botín.'}[id])+'</span></button>').join('')+'</div>';}
function guide(){modal(head('BIENVENIDO A '+GAME.title.toUpperCase(),MODERN?'El mando es tuyo.':'Un reino por levantar.')+'<p>'+GAME.tagline+' Construye una base, mejora cada edificio y prepara un ejército para conquistar doce territorios.</p><div class="guide-steps">'+[['01 · PRODUCE','Recoge y reinvierte','Las minas, viviendas y productores acumulan recursos. Tócalos o usa Recoger producción. Mejora almacenes para ampliar las reservas.'],['02 · CONSTRUYE','Cada edificio tiene su función','Elige un plano en Construir, marca una casilla libre y confirma. Hay dos constructores; el taller permite añadir más.'],['03 · MEJORA','Un nuevo nivel, nuevas posibilidades','Toca un edificio → Ver mejora. El nivel principal limita los demás. Completar todas sus mejoras ofrece un descuento del 20% al siguiente nivel principal.'],['04 · CONQUISTA','Entrena, despliega y dirige','En Ejército encontrarás '+Object.keys(E.UNITS).length+' tipos de unidad. Espía una base en Campaña, ataca y despliega en la franja azul. Las bajas son permanentes.']].map(([n,t,p])=>'<div class="guide-step"><b>'+n+'</b><h3>'+t+'</h3><p>'+p+'</p></div>').join('')+'</div><h3>Elige la dificultad</h3>'+difficultyOptions()+'<details><summary class="tiny">Controles de cámara y tropas</summary><p class="tiny">Rueda: zoom. Botón central o Alt + arrastrar: cámara. En celular: arrastra y pellizca. Q/E: girar. Espacio: centrar. En combate: toca tropas o arrastra un recuadro, luego toca el destino. Clic derecho: orden. A: avanzar atacando. S: detener. Ctrl + 1–9: guardar grupo; 1–9: recuperarlo.</p></details><p class="offline-note">Partida local contra IA, sin cuenta. El guardado de este juego es independiente. Exporta una copia desde Ajustes.</p><button class="primary wide" data-action="begin">'+icon('flag')+' Empezar a jugar</button>');}
function settings(){modal(head('PREFERENCIAS Y PARTIDA','Tu mundo, guardado aquí.')+'<h3>Dificultad</h3>'+difficultyOptions()+'<label class="settings-row"><span>Sonido</span><input id="sound-enabled" type="checkbox" '+(state.settings.sound?'checked':'')+'></label><label class="settings-row"><span>Volumen</span><input id="sound-volume" type="range" min="0" max="100" value="'+state.settings.volume*100+'"></label><div class="action-row"><button data-action="export">'+icon('save')+' Exportar copia</button><button data-action="import">Importar copia</button></div><button class="wide secondary" data-action="help">'+icon('help')+' Cómo jugar</button><button class="wide secondary" data-action="install">Instalar página</button><p class="tiny" style="margin-top:15px">Producción y colas se calculan hasta ocho horas durante tu ausencia. Las batallas se guardan y se reanudan al volver. Los enemigos y las alianzas pertenecen a la IA local.</p><div class="links"><a href="'+GAME.repo+'" target="_blank" rel="noopener">Repositorio</a><a href="'+GAME.sibling+'">'+GAME.siblingName+'</a><a href="https://oscard0823.github.io/Pagina-Principal/">Ecosistema Auralis</a></div><div class="section-label">'+GAME.title+' · Alpha '+GAME.version+'</div><button class="danger wide" data-action="new-dialog">Nueva base</button>');}
function upgradePreview(id){const b=state.buildings.find(b=>b.id===id);if(!b)return;const q=E.upgradeQuote(state,id),old=E.buildingStats(b.type,b.level),next=E.buildingStats(b.type,Math.min(10,b.level+1)),spec=E.BUILDINGS[b.type];modal(head('EVOLUCIÓN DE TU BASE',esc(spec.name))+'<div class="compare"><div>'+img(b.type,b.level)+'<small>Nivel '+b.level+'</small></div><span>'+icon('arrow')+'</span><div>'+img(b.type,q.next)+'<small>Nivel '+q.next+'</small></div></div><div class="stat-row"><span>Vida</span><strong>'+old.hp+' → '+next.hp+'</strong></div>'+(old.rate?'<div class="stat-row"><span>Producción / segundo</span><strong>'+old.rate.toFixed(2)+' → '+next.rate.toFixed(2)+'</strong></div><div class="stat-row"><span>Capacidad de producción</span><strong>'+old.capacity+' → '+next.capacity+'</strong></div>':'')+(old.attack?'<div class="stat-row"><span>Daño</span><strong>'+old.attack+' → '+next.attack+'</strong></div>':'')+'<div class="stat-row"><span>Tiempo de obra</span><strong>'+clock(q.duration)+'</strong></div>'+(q.discount?'<p class="warning">Base completamente mejorada: descuento del 20% en esta mejora principal.</p>':'')+(!q.ok?'<p class="warning">'+esc(q.message)+'</p>':'')+cost(q.cost)+'<button class="primary wide" data-action="upgrade-confirm" data-id="'+id+'" '+(!q.ok||!E.affordable(state,q.cost)||E.usedBuilders(state)>=E.builders(state)?'disabled':'')+'>'+icon('build')+' Mejorar al nivel '+q.next+'</button>');}
function unitDetail(type){const u=E.UNITS[type],level=E.unitLevel(state,type),st=E.unitStats(type,level),q=E.researchQuote(state,type);modal(head('TROPAS Y ESPECIALIZACIÓN',esc(u.name))+img(type,level,true,'hero-image')+'<span class="level-pill">GRADO '+level+' / 5</span><div class="stat-row"><span>Vida / daño</span><strong>'+st.hp+' / '+(u.heal?'Cura '+st.heal:st.damage)+'</strong></div><div class="stat-row"><span>Alcance / velocidad</span><strong>'+u.range+' / '+u.speed+'</strong></div><div class="stat-row"><span>Capacidad / entrenamiento</span><strong>'+u.pop+' / '+clock(u.time)+'</strong></div><div class="stat-row"><span>Edificio requerido</span><strong>'+esc(E.BUILDINGS[u.factory].name)+' '+u.required+'</strong></div>'+(u.siege?'<p class="warning">Especialista de asedio: daño adicional contra edificios.</p>':u.flying?'<p class="warning">Unidad aérea: atraviesa obstáculos; vulnerable a defensas antiaéreas y tropas a distancia.</p>':u.heal?'<p class="warning">Apoyo: cura a los aliados heridos que se encuentren a su alcance.</p>':'')+'<h3 style="margin-top:18px">Investigación al grado '+q.level+'</h3><p class="tiny">Mejora vida y daño un 20% de la base por grado. Los supervivientes conservan su proporción de vida.</p>'+(!q.ok?'<p class="warning">'+esc(q.message)+'</p>':cost(q.cost)+'<p class="tiny">'+clock(q.duration)+' de investigación.</p>')+'<button class="primary wide" data-action="research" data-type="'+type+'" '+(!q.ok||!E.affordable(state,q.cost)?'disabled':'')+'>'+icon('research')+' Investigar</button>');}
function scout(index){const c=E.camp(state,index),troops={};for(const u of c.enemies)troops[u.type]=(troops[u.type]||0)+1;modal(head('INTELIGENCIA · OBJETIVO '+(index+1),esc(c.name))+img('hq',c.level,false,'hero-image')+'<p>Base de '+GAME.enemy+'. '+c.buildings.length+' edificios y '+c.enemies.length+' defensores. Destruye su edificio principal para ganar; alcanza el 50% y el 100% de destrucción para conseguir más estrellas.</p><div class="section-label">Defensores detectados</div><p>'+Object.entries(troops).map(([id,n])=>n+' '+esc(E.UNITS[id].name)).join(' · ')+'</p><div class="section-label">Botín '+(state.completed[index]?'de repetición: 25%':'de primera conquista')+'</div>'+cost(Object.fromEntries(Object.entries(c.reward).map(([k,v])=>[k,state.completed[index]?Math.round(v*.25):v])))+'<p class="warning">Tienes '+state.army.length+' tropas preparadas. Los soldados caídos se pierden; puedes retirarte y recuperar los supervivientes y las reservas sin desplegar.</p><button class="primary wide" data-action="attack" data-index="'+index+'" '+(!state.army.length?'disabled':'')+'>'+icon('army')+' Iniciar ataque</button>');}
function battleResult(){const r=state.lastBattle;if(!r)return;modal(head(r.kind==='raid'?'DEFENSA DE LA BASE':'INFORME DE OPERACIÓN',r.victory?'La victoria es tuya.':'Cada batalla enseña.')+'<div class="result-medal">'+icon(r.victory?'shield':'flag').replace('class="icon ','style="width:64px;height:64px" class="icon ')+'</div><div class="result-title"><p>'+esc(r.name)+'</p><span class="stars">'+'★'.repeat(r.stars)+'☆'.repeat(3-r.stars)+'</span></div><div class="result-stats"><div><b>'+r.destroyed+' / '+r.total+'</b><span>Edificios destruidos</span></div><div><b>'+r.survivors+'</b><span>Supervivientes</span></div><div><b>'+r.lost+'</b><span>Bajas permanentes</span></div><div><b>'+r.reserve+'</b><span>Reservas recuperadas</span></div></div>'+cost(r.reward)+'<p>Los supervivientes regresaron. '+(r.victory?'Invierte el botín en mejoras y prepara la siguiente operación.':'Reúne refuerzos y revisa la composición del ejército. Construye un hospital para curar las unidades heridas.')+'</p><button class="primary wide" data-action="close-modal">Volver a la base</button>');sound.play(r.victory?'win':'alert');}
function pick(point){if(loadError)return;if(point.box){const b=state.battle;if(!b)return;selected=b.units.filter(u=>u.side==='player'&&u.hp>0).filter(u=>{const p=scene.screen(u.x,u.y,.5);return p.x>=point.box.x1&&p.x<=point.box.x2&&p.y>=point.box.y1&&p.y<=point.box.y2;}).map(u=>u.id);deployType=null;dirty=true;return;}const x=Math.floor(point.x),y=Math.floor(point.y);if(tool==='clear'){act(E.clearTerrain(state,x,y),'build');return;}if(tool||moving){candidate={x,y};const type=tool||state.buildings.find(b=>b.id===moving).type,result=E.placement(state,type,x,y,moving);scene.ghost.material.color.set(result.ok?'#c3d99d':'#ef8c75');if(!result.ok)toast(result.message);dirty=true;return;}
 const b=state.battle;if(b){if(deployType){act(E.deploy(state,deployType,point.x,point.y),'order');if(!b.reserve.some(u=>u.type===deployType))deployType=null;dirty=true;return;}const unit=b.units.filter(u=>u.side==='player'&&u.hp>0).find(u=>Math.hypot(u.x-point.x,u.y-point.y)<.8);if(unit&&point.button!==2){selected=point.append?[...new Set([...selected,unit.id])]:[unit.id];sound.play('select');}else if(selected.length){act(E.order(state,selected,point.x,point.y,command),'order');}dirty=true;return;}
 const building=state.buildings.find(b=>x>=b.x&&x<b.x+E.BUILDINGS[b.type].size&&y>=b.y&&y<b.y+E.BUILDINGS[b.type].size);if(building){selected=[building.id];tab='base';sound.play('select');if(E.BUILDINGS[building.type].resource&&building.stored>=1&&!building.job)act(E.collect(state,building.id),'collect');}else selected=[];dirty=true;}
function exportSave(){const raw=loadError?broken:E.encode(state),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));a.download=GAME.id+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Copia exportada.');}
let installPrompt=null;addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;await sound.unlock();const a=button.dataset.action,type=button.dataset.type,id=button.dataset.id,index=Number(button.dataset.index);if(loadError&&!['close-modal','settings','export','import','new-dialog','new','confirm-import'].includes(a)){toast('Importa una copia válida o crea una base nueva desde Ajustes.');return;}try{
 if(a==='tab'){if(state.battle){toast('Termina el combate para gestionar la base.');return;}setTab(type);}
 else if(a==='close-panel'){tab='base';dirty=true;}
 else if(a==='deselect'){selected=[];dirty=true;}
 else if(a==='category'){category=type;dirty=true;}
 else if(a==='unit-category'){unitCategory=type;dirty=true;}
 else if(a==='place'||a==='move-building'||a==='clear-terrain'){tool=a==='clear-terrain'?'clear':a==='place'?type:null;moving=a==='move-building'?id:null;candidate=null;tab='base';selected=[];scene.setPlacement(tool==='clear'?null:tool||state.buildings.find(b=>b.id===moving)?.type);dirty=true;toast(a==='clear-terrain'?'Toca un árbol o roca. Se pagan 15 de oro y se recuperan materiales.':'Marca una casilla del mapa y confirma.');}
 else if(a==='cancel-placement'){tool=null;moving=null;candidate=null;scene.setPlacement(null);dirty=true;}
 else if(a==='confirm-placement'){if(!candidate)return;const r=moving?E.moveBuilding(state,moving,candidate.x,candidate.y):E.build(state,tool,candidate.x,candidate.y);act(r,'build');if(r.ok){tool=null;moving=null;candidate=null;scene.setPlacement(null);}}
 else if(a==='collect'){act(E.collect(state,id),'collect');}
 else if(a==='collect-all'){act(E.collectAll(state),'collect');}
 else if(a==='upgrade-preview'){upgradePreview(id);}
 else if(a==='upgrade-confirm'){const r=act(E.upgrade(state,id),'build');if(r.ok)$('#modal').close();}
 else if(a==='repair'){act(E.repair(state,id),'build');}
 else if(a==='train'){act(E.recruit(state,type),'build');}
 else if(a==='cancel-training'){act(E.cancelTraining(state,id));}
 else if(a==='unit-detail'){unitDetail(type);}
 else if(a==='research'){const r=act(E.research(state,type),'build');if(r.ok)$('#modal').close();}
 else if(a==='scout'){scout(index);}
 else if(a==='attack'){const r=act(E.startAttack(state,index),'order');if(r.ok){$('#modal').close();tab='base';selected=[];deployType=null;scene.home();}}
 else if(a==='deployment-type'){deployType=type;selected=[];dirty=true;toast('Toca la franja azul para desplegar '+E.UNITS[type].name+'.');}
 else if(a==='deploy-all'){act(E.deployAll(state),'order');selected=state.battle.units.filter(u=>u.side==='player'&&u.hp>0).map(u=>u.id);deployType=null;}
 else if(a==='select-all'){selected=state.battle?.units.filter(u=>u.side==='player'&&u.hp>0).map(u=>u.id)||[];deployType=null;dirty=true;}
 else if(a==='attack-mode'||a==='move-mode'){command=a==='attack-mode'?'attack':'move';deployType=null;dirty=true;toast(command==='attack'?'Selecciona tropas y toca un destino: avanzarán atacando.':'Selecciona tropas y toca un destino.');}
 else if(a==='hold'){if(state.battle)for(const u of state.battle.units.filter(u=>u.side==='player'&&selected.includes(u.id)))u.order={kind:'hold',x:u.x,y:u.y};toast('Mantener posición.');save();}
 else if(a==='retreat'){modal(head('TU EJÉRCITO','¿Finalizar la operación?')+'<p>Los supervivientes y las reservas volverán a la base. Se conserva el daño recibido. '+(state.battle?.kind==='raid'?'Si aún hay invasores se considerará una defensa perdida.':'Si el edificio principal rival ya cayó, conservarás la victoria y el botín.')+'</p><div class="action-row"><button data-action="close-modal">Continuar combate</button><button class="primary" data-action="retreat-confirm">Retirar ejército</button></div>');}
 else if(a==='retreat-confirm'){act(E.finishBattle(state),'order');selected=[];deployType=null;scene.home();battleResult();}
 else if(a==='claim'){act(E.claimQuest(state,id),'collect');}
 else if(a==='ally'){act(E.ally(state,id),'collect');}
 else if(a==='difficulty'){act(E.setDifficulty(state,type));$$('[data-action=difficulty]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.type===state.difficulty)));}
 else if(a==='settings'){settings();}
 else if(a==='help'){guide();}
 else if(a==='begin'){state.tutorial=true;save();$('#modal').close();}
 else if(a==='close-modal'){$('#modal').close();}
 else if(a==='zoom-in'||a==='zoom-out'){scene.zoom=Math.max(.5,Math.min(2.1,scene.zoom+(a==='zoom-in'?.15:-.15)));scene.updateCamera();}
 else if(a==='center'){scene.home();}
 else if(a==='rotate'){scene.turn();}
 else if(a==='pan'){scene.panMode=!scene.panMode;button.setAttribute('aria-pressed',String(scene.panMode));}
 else if(a==='sound'){state.settings.sound=!state.settings.sound;sound.enabled=state.settings.sound;await sound.unlock();save();toast(sound.enabled?'Sonido activado.':'Sonido desactivado.');}
 else if(a==='export'){exportSave();}
 else if(a==='import'){$('#import-file').click();}
 else if(a==='confirm-import'){state=pendingImport;pendingImport=null;loadError='';broken='';selected=[];tab='base';tool=null;moving=null;candidate=null;scene.staticKey='';sound.enabled=state.settings.sound;sound.volume=state.settings.volume;save();$('#modal').close();dirty=true;scene.home();toast('Partida importada.');}
 else if(a==='new-dialog'){modal(head('UNA NUEVA HISTORIA','¿Fundar otra base?')+'<p>La base local de '+GAME.title+' se reemplazará. Exporta una copia si quieres conservarla.</p><div class="action-row"><button data-action="export">Exportar primero</button><button class="danger" data-action="new">Crear base nueva</button></div>');}
 else if(a==='new'){state=E.createState(undefined,state.difficulty);loadError='';broken='';selected=[];tab='base';tool=null;moving=null;candidate=null;save();scene.staticKey='';scene.home();dirty=true;guide();}
 else if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Usa «Instalar aplicación» o «Añadir a pantalla de inicio» en el menú del navegador.');}
 }catch(error){console.error(error);toast('No se pudo completar la acción. La partida se conserva.');}});
document.addEventListener('input',event=>{if(event.target.id==='sound-volume'){state.settings.volume=Number(event.target.value)/100;sound.volume=state.settings.volume;save();}});document.addEventListener('change',event=>{if(event.target.id==='sound-enabled'){state.settings.sound=event.target.checked;sound.enabled=state.settings.sound;sound.unlock();save();}});
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>3000000){toast('La copia supera el tamaño permitido.');return;}try{pendingImport=E.decode(await file.text());modal(head('RESTABLECER PARTIDA','Tu copia está preparada.')+'<p>'+GAME.hq+' nivel '+E.hqLevel(pendingImport)+' · '+pendingImport.buildings.length+' edificios · '+pendingImport.army.length+' tropas. Esta copia reemplazará la base local de este juego.</p><div class="action-row"><button data-action="export">Exportar base actual</button><button class="primary" data-action="confirm-import">Importar esta copia</button></div>');}catch(error){toast('No se pudo importar: '+error.message);}});
const groups=new Map();document.addEventListener('keydown',event=>{if(event.target.matches('input,textarea,select')||$('#modal').open)return;const k=event.key.toLowerCase();if(k==='escape'){tool=null;moving=null;candidate=null;selected=[];tab='base';dirty=true;}if(k==='q'){scene.yaw-=Math.PI/4;scene.updateCamera();}if(k==='e')scene.turn();if(k===' '){event.preventDefault();scene.home();}if(state.battle){if(k==='a'){command='attack';deployType=null;dirty=true;}if(k==='s')for(const u of state.battle.units.filter(u=>selected.includes(u.id)))u.order={kind:'hold',x:u.x,y:u.y};if(/^[1-9]$/.test(k)){if(event.ctrlKey){event.preventDefault();groups.set(k,[...selected]);}else selected=groups.get(k)||[];}}});
function paintOverlay(){const r=$('#field').getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,1.5);if(overlay.width!==Math.round(r.width*dpr)||overlay.height!==Math.round(r.height*dpr)){overlay.width=Math.round(r.width*dpr);overlay.height=Math.round(r.height*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);if(!scene)return;const b=state.battle,buildings=b?.buildings||state.buildings;for(const building of buildings){if(building.hp<=0)continue;const size=E.BUILDINGS[building.type].size,p=scene.screen(building.x+size/2,building.y+size/2,2),spec=E.BUILDINGS[building.type];if(p.x<0||p.x>r.width||p.y<0||p.y>r.height)continue;if(building.job){const ratio=(state.time-building.job.started)/(building.job.ends-building.job.started);ctx.fillStyle='#122c2bd9';ctx.fillRect(p.x-23,p.y-5,46,6);ctx.fillStyle='#dbc487';ctx.fillRect(p.x-23,p.y-5,46*Math.min(1,ratio),6);}else if(!b&&spec.resource&&building.stored>=10){ctx.fillStyle='#1b3629e8';ctx.beginPath();ctx.roundRect(p.x-20,p.y-11,40,22,5);ctx.fill();ctx.fillStyle='#e3c17c';ctx.font='600 10px Segoe UI';ctx.textAlign='center';ctx.fillText('+'+fmt(building.stored),p.x,p.y+4);}if(b){const max=building.maxHp||E.buildingStats(building.type,building.level).hp;ctx.fillStyle='#14332ade';ctx.fillRect(p.x-21,p.y-8,42,4);ctx.fillStyle=building.side==='enemy'?'#dc8e76':'#adc9a4';ctx.fillRect(p.x-21,p.y-8,42*building.hp/max,4);}}
 if(b)for(const u of b.units.filter(u=>u.hp>0)){if(u.hp>=u.maxHp&&!selected.includes(u.id))continue;const p=scene.screen(u.x,u.y,E.UNITS[u.type].flying?3:1.3);ctx.fillStyle='#16312ee0';ctx.fillRect(p.x-12,p.y-8,24,3);ctx.fillStyle=u.side==='enemy'?'#e5937b':'#bbd59f';ctx.fillRect(p.x-12,p.y-8,24*u.hp/u.maxHp,3);}if(scene.selectionRect){const box=scene.selectionRect,rect=scene.canvas.getBoundingClientRect();ctx.fillStyle='#c1dba41c';ctx.strokeStyle='#c1dba4';ctx.fillRect(box.x-rect.x,box.y-rect.y,box.x2-box.x,box.y2-box.y);ctx.strokeRect(box.x-rect.x,box.y-rect.y,box.x2-box.x,box.y2-box.y);}}
addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){save();}lastFrame=performance.now();});
try{await ready;}catch(error){console.warn('Se usarán los modelos geométricos de respaldo.',error);}try{scene=new Battlefield($('#world'),pick);}catch(error){$('#loading').innerHTML='<span class="loading-mark">A</span><p>Este navegador no pudo iniciar WebGL.</p><small>Prueba Chrome, Edge, Firefox o Safari con aceleración gráfica.</small><button onclick="location.reload()">Volver a intentar</button>';throw error;}
$('#loading').remove();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(loadError)modal(head('REVISAR COPIA LOCAL','La partida necesita revisión.')+'<p>'+esc(loadError)+'. La copia original se conserva y el guardado está detenido. Exporta el archivo para conservarlo, importa una copia válida o crea una base nueva.</p><div class="action-row"><button data-action="export">Exportar copia original</button><button data-action="import">Importar copia</button><button data-action="new-dialog">Nueva base</button></div>');else if(!state.tutorial)guide();
let lastFrame=performance.now(),lastUi=0,lastPaint=0,lastShot=0;function frame(now){const dt=Math.min(.12,(now-lastFrame)/1000);lastFrame=now;if(!document.hidden&&!loadError){const previous=state.battle,buildCount=state.buildings.filter(b=>b.job).length;if($('#modal').open)E.tickEconomy(state,dt);else E.step(state,dt);if(previous&&!state.battle){selected=[];deployType=null;tab='base';save();battleResult();dirty=true;scene.home();}if(!previous&&state.battle){tab='base';selected=[];sound.play('alert');save();dirty=true;scene.home();}if(state.battle?.effects.length&&now-lastShot>250){const shot=state.battle.effects.at(-1);if(state.battle.elapsed-shot.at<.13){sound.play('attack');lastShot=now;}}if(buildCount!==state.buildings.filter(b=>b.job).length){sound.play('complete');dirty=true;}if(now-lastUi>900){renderHud();if(!document.activeElement.matches('input,select')){renderPanel();renderInspector();renderDock();}nav();lastUi=now;if(state.time-lastSave>8)save();}if(dirty)render();if(now-lastPaint>40){scene.draw(state,{selected,placement:tool==='clear'?null:tool||state.buildings.find(b=>b.id===moving)?.type});paintOverlay();lastPaint=now;}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
